# ── 文件遍历、读取、MD5 工具 ──────────────────────────────────────────
import os
import hashlib

from config.settings import settings
from utils.logger import get_logger

logger = get_logger(__name__)


def walk_project(
    project_root: str,
    suffixes: list[str] | None = None,
) -> list[str]:
    """
    递归遍历项目，返回所有匹配后缀的文件绝对路径列表。

    :param project_root: 项目根目录
    :param suffixes:     目标后缀列表，如 [".py"]；None 则返回所有文件
    :return:             绝对路径列表
    """
    root = os.path.abspath(project_root)
    if not os.path.isdir(root):
        logger.error(f"项目路径不存在或不是目录: {root}")
        return []

    exclude = set(settings.EXCLUDE_DIRS)
    results: list[str] = []

    for dirpath, dirnames, filenames in os.walk(root):
        # 原地过滤，防止 os.walk 进入排除目录
        dirnames[:] = [
            d for d in dirnames
            if d not in exclude and not d.startswith(".")
        ]
        for fname in filenames:
            if suffixes is None or os.path.splitext(fname)[1] in suffixes:
                results.append(os.path.join(dirpath, fname))

    logger.info(f"遍历完成: {root}，共 {len(results)} 个目标文件")
    return results


def read_file(path: str) -> str:
    """读取文件内容，依次尝试 utf-8 / gbk，失败返回空串"""
    for encoding in ("utf-8", "gbk"):
        try:
            with open(path, "r", encoding=encoding) as f:
                return f.read()
        except UnicodeDecodeError:
            continue
        except OSError as e:
            logger.error(f"文件读取失败: {path} — {e}")
            return ""
    logger.warning(f"编码识别失败，跳过: {path}")
    return ""


def file_md5(path: str) -> str:
    """计算文件 MD5，用于增量更新时的变更检测"""
    if not os.path.isfile(path):
        return ""
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

# core/parser/factory.py
# ── 可插拔解析器工厂 ──────────────────────────────────────────────────
# 开闭原则：新增语言只需实现 BaseParser + 调用 register()，工厂代码不动。
from __future__ import annotations

from typing import Type

from core.parser.base import BaseParser
from utils.logger import get_logger

logger = get_logger(__name__)


class ParserFactory:
    """
    解析器工厂。
    注册示例：
        ParserFactory.register(PythonParser)
    获取示例：
        parser = ParserFactory.get(".py")
    """

    _registry: dict[str, Type[BaseParser]] = {}

    # ── 注册 ─────────────────────────────────────────
    @classmethod
    def register(cls, parser_cls: Type[BaseParser]) -> None:
        """注册解析器类；同一后缀重复注册会覆盖并警告"""
        instance = parser_cls()
        for suffix in instance.supported_suffixes:
            if suffix in cls._registry:
                logger.warning(
                    f"后缀 {suffix!r} 解析器已存在，将覆盖: "
                    f"{cls._registry[suffix].__name__} → {parser_cls.__name__}"
                )
            cls._registry[suffix] = parser_cls
            logger.debug(f"注册解析器: {parser_cls.__name__} ← {suffix}")

    # ── 获取 ─────────────────────────────────────────
    @classmethod
    def get(cls, suffix: str) -> BaseParser:
        """
        按文件后缀返回解析器实例。
        :raises ValueError: 未注册该后缀时抛出
        """
        parser_cls = cls._registry.get(suffix)
        if parser_cls is None:
            raise ValueError(
                f"没有注册支持后缀 {suffix!r} 的解析器。"
                f"已注册: {list(cls._registry.keys())}"
            )
        return parser_cls()

    # ── 查询 ─────────────────────────────────────────
    @classmethod
    def supported_suffixes(cls) -> list[str]:
        """返回所有已注册的文件后缀"""
        return list(cls._registry.keys())

    @classmethod
    def is_supported(cls, suffix: str) -> bool:
        return suffix in cls._registry


